ALTER TABLE public.site_settings ADD COLUMN IF NOT EXISTS dashboard_lang text NOT NULL DEFAULT 'nl', ADD COLUMN IF NOT EXISTS default_lang text NOT NULL DEFAULT 'nl', ADD COLUMN IF NOT EXISTS languages text[] NOT NULL DEFAULT ARRAY['nl'], ADD COLUMN IF NOT EXISTS auto_translate boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS site_domain text NOT NULL DEFAULT '';
ALTER TABLE public.site_settings ALTER COLUMN languages SET DEFAULT ARRAY['nl'];
ALTER TABLE public.site_settings ALTER COLUMN auto_translate SET DEFAULT false;
CREATE OR REPLACE FUNCTION public.can_edit(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role::text IN ('admin','editor')) $$;
GRANT EXECUTE ON FUNCTION public.can_edit(uuid) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.can_edit(uuid) FROM public, anon;
CREATE TABLE public.cms_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, perms jsonb NOT NULL DEFAULT '{"text":true,"images":true,"blocks":false,"translate":false,"pages":false}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cms_roles TO authenticated;
GRANT ALL ON public.cms_roles TO service_role;
ALTER TABLE public.cms_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read role profiles" ON public.cms_roles FOR SELECT TO authenticated USING (public.can_edit(auth.uid()));
CREATE POLICY "Admins manage role profiles" ON public.cms_roles FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
ALTER TABLE public.user_roles ADD COLUMN IF NOT EXISTS cms_role_id uuid REFERENCES public.cms_roles(id) ON DELETE SET NULL;
CREATE OR REPLACE FUNCTION public.has_perm(_user_id uuid,_perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR EXISTS (SELECT 1 FROM public.user_roles ur LEFT JOIN public.cms_roles c ON c.id=ur.cms_role_id WHERE ur.user_id=_user_id AND ur.role::text='editor' AND COALESCE((c.perms->>_perm)::boolean,_perm IN ('text','images'))) $$;
CREATE OR REPLACE FUNCTION public.my_perms() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('text',public.has_perm(auth.uid(),'text'),'images',public.has_perm(auth.uid(),'images'),'blocks',public.has_perm(auth.uid(),'blocks'),'translate',public.has_perm(auth.uid(),'translate'),'pages',public.has_perm(auth.uid(),'pages')) $$;
REVOKE EXECUTE ON FUNCTION public.has_perm(uuid,text),public.my_perms() FROM public,anon;
GRANT EXECUTE ON FUNCTION public.has_perm(uuid,text),public.my_perms() TO authenticated;
CREATE TABLE public.page_content (path text NOT NULL,state text NOT NULL CHECK(state IN ('draft','published')),data jsonb NOT NULL DEFAULT '{}',layout jsonb,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid,PRIMARY KEY(path,state));
GRANT SELECT ON public.page_content TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.page_content TO authenticated;
GRANT ALL ON public.page_content TO service_role;
ALTER TABLE public.page_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reads published edits" ON public.page_content FOR SELECT TO anon,authenticated USING(state='published');
CREATE POLICY "Staff manage edits" ON public.page_content FOR ALL TO authenticated USING(public.can_edit(auth.uid())) WITH CHECK(public.can_edit(auth.uid()));
CREATE TABLE public.page_seo(path text PRIMARY KEY,title text,description text,noindex boolean NOT NULL DEFAULT false,nofollow boolean NOT NULL DEFAULT false,keywords text,canonical text,redirects text,og_title text,og_description text,og_image text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.page_seo TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.page_seo TO authenticated;
GRANT ALL ON public.page_seo TO service_role;
ALTER TABLE public.page_seo ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reads SEO" ON public.page_seo FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Staff manage SEO" ON public.page_seo FOR ALL TO authenticated USING(public.can_edit(auth.uid())) WITH CHECK(public.can_edit(auth.uid()));
CREATE TABLE public.page_settings(path text PRIMARY KEY,name_nl text,name_en text,hidden_in_menu boolean NOT NULL DEFAULT false,disabled boolean NOT NULL DEFAULT false,deleted boolean NOT NULL DEFAULT false,hide_in_search boolean NOT NULL DEFAULT false,encrypted_url boolean NOT NULL DEFAULT false,sort_order integer,parent_path text,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.page_settings TO anon;
GRANT SELECT,INSERT,UPDATE ON public.page_settings TO authenticated;
GRANT ALL ON public.page_settings TO service_role;
ALTER TABLE public.page_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reads page settings" ON public.page_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Staff manage page settings" ON public.page_settings FOR ALL TO authenticated USING(public.can_edit(auth.uid())) WITH CHECK(public.can_edit(auth.uid()));
CREATE TABLE public.custom_pages(path text PRIMARY KEY CHECK(path ~ '^/(nl|en)/[a-z0-9-]+$'),source_path text NOT NULL,pair_path text,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid);
GRANT SELECT ON public.custom_pages TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.custom_pages TO authenticated;
GRANT ALL ON public.custom_pages TO service_role;
ALTER TABLE public.custom_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reads custom pages" ON public.custom_pages FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Page managers manage pages" ON public.custom_pages FOR ALL TO authenticated USING(public.has_perm(auth.uid(),'pages')) WITH CHECK(public.has_perm(auth.uid(),'pages'));
CREATE TABLE public.block_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,html text NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.block_templates TO authenticated;
GRANT ALL ON public.block_templates TO service_role;
ALTER TABLE public.block_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff reads templates" ON public.block_templates FOR SELECT TO authenticated USING(public.can_edit(auth.uid()));
CREATE POLICY "Block managers manage templates" ON public.block_templates FOR ALL TO authenticated USING(public.has_perm(auth.uid(),'blocks')) WITH CHECK(public.has_perm(auth.uid(),'blocks'));
CREATE TABLE public.media_folders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 60),created_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.media_folders TO authenticated;
GRANT ALL ON public.media_folders TO service_role;
ALTER TABLE public.media_folders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff manage folders" ON public.media_folders FOR ALL TO authenticated USING(public.can_edit(auth.uid())) WITH CHECK(public.can_edit(auth.uid()));
ALTER TABLE public.media ADD COLUMN IF NOT EXISTS storage_path text NOT NULL DEFAULT '',ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'image',ADD COLUMN IF NOT EXISTS created_by uuid,ADD COLUMN IF NOT EXISTS alt text,ADD COLUMN IF NOT EXISTS mime text,ADD COLUMN IF NOT EXISTS folder_id uuid REFERENCES public.media_folders(id) ON DELETE SET NULL;
ALTER TABLE public.media ALTER COLUMN path SET DEFAULT '';
CREATE TABLE public.page_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),path text NOT NULL,data jsonb NOT NULL DEFAULT '{}',layout jsonb,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid);
GRANT SELECT ON public.page_revisions TO authenticated;
GRANT ALL ON public.page_revisions TO service_role;
ALTER TABLE public.page_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff reads revisions" ON public.page_revisions FOR SELECT TO authenticated USING(public.can_edit(auth.uid()));
CREATE TABLE public.audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),actor uuid,actor_email text,action text NOT NULL,target text);
GRANT SELECT ON public.audit_log TO authenticated;
GRANT ALL ON public.audit_log TO service_role;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read activity" ON public.audit_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.site_backups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,created_by_email text,data jsonb NOT NULL);
GRANT SELECT ON public.site_backups TO authenticated;
GRANT ALL ON public.site_backups TO service_role;
ALTER TABLE public.site_backups ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff reads backups" ON public.site_backups FOR SELECT TO authenticated USING(public.can_edit(auth.uid()));
CREATE OR REPLACE FUNCTION public.publish_all_drafts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.can_edit(auth.uid()) THEN RAISE EXCEPTION 'Geen rechten'; END IF; INSERT INTO public.page_content(path,state,data,layout,updated_at,updated_by) SELECT path,'published',data,layout,now(),auth.uid() FROM public.page_content WHERE state='draft' ON CONFLICT(path,state) DO UPDATE SET data=EXCLUDED.data,layout=EXCLUDED.layout,updated_at=now(),updated_by=EXCLUDED.updated_by; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE EXECUTE ON FUNCTION public.publish_all_drafts() FROM public,anon;
GRANT EXECUTE ON FUNCTION public.publish_all_drafts() TO authenticated;
CREATE OR REPLACE FUNCTION public.public_site_languages() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('default_lang',default_lang,'languages',languages) FROM public.site_settings WHERE id=1 $$;
GRANT EXECUTE ON FUNCTION public.public_site_languages() TO anon,authenticated;
COMMENT ON TABLE public.pages IS 'DEPRECATED: CMS now uses page_content, page_settings and custom_pages; previous content retained';
COMMENT ON TABLE public.blocks IS 'DEPRECATED: previous block CMS content retained; new CMS uses HTML layout overrides';